def check_lc16(tgraph):
    return tgraph.check_chain(nodes=["R_CORE", "SW_CORE_BRANCH", "R_BRANCH", "SW_BRANCH", "BPC1"])


def check_lc17(tgraph):
    issues = []
    fixed_nodes = ["R_CORE", "R_BRANCH", "FIREWALL", "INTERNET"]
    for nid in fixed_nodes:
        node = tgraph.node(nid)
        if node is None:
            issues.append({
                "message": f"Node {nid} not found in graph.",
                "severity": "error",
                "location": f"nodes.{nid}",
                "details": {
                    "issue_kind": "logical.custom.missing_node",
                    "constraint_id": "lc17",
                    "repair_target": "graph",
                    "node": nid,
                },
            })
            continue
        ports = node.get("ports", [])
        for p in ports:
            pname = p.get("id", "")
            ip = p.get("ip")
            if not ip:
                issues.append({
                    "message": f"Port {pname} on {nid} must have a fixed IPv4 address.",
                    "severity": "error",
                    "location": f"nodes.{nid}.ports.{pname}",
                    "details": {
                        "issue_kind": "logical.custom.missing_fixed_ip",
                        "constraint_id": "lc17",
                        "repair_target": "graph",
                        "node": nid,
                        "port": pname,
                    },
                })
    return issues if issues else []

